const now = new Date();
const hour = now.getHours();
const minute = now.getMinutes();
const day = now.getDay();

const isWeekday = day >= 1 && day <= 5;
const isMarketHours = (hour > 9 || (hour === 9 && minute >= 15)) && (hour < 15 || (hour === 15 && minute <= 30));
const isResearchTime = isMarketHours && !(hour === 9 && minute < 20) && !(hour === 15 && minute > 0);

return [{
  canProceed: isWeekday && isResearchTime,
  currentTime: now.toISOString(),
  marketPhase: hour < 10 ? 'OPENING' : hour < 12 ? 'MORNING' : hour < 14 ? 'AFTERNOON' : 'CLOSING',
  tradingSession: isResearchTime ? 'ACTIVE' : 'CLOSED'
}];

